const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.image;dialog.showModal()}));dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
fetch('videos.json').then(r=>{if(!r.ok)throw new Error('Could not load video archive');return r.json()}).then(data=>{const root=document.querySelector('#videos');data.items.forEach((v,i)=>{const a=document.createElement('a');a.className='video-row';a.href='https://v.douyin.com/'+v[4]+'/';a.target='_blank';a.rel='noopener noreferrer';const n=document.createElement('span');n.className='number';n.textContent=String(i+1).padStart(2,'0');const desc=document.createElement('div');const h=document.createElement('h4');h.textContent=v[0];const p=document.createElement('p');p.textContent=v[3];desc.append(h,p);const count=document.createElement('span');count.className='likes';count.textContent=data.stats[i][0];const small=document.createElement('small');small.textContent='LIKES / 点赞';count.append(small);const arrow=document.createElement('span');arrow.textContent='↗';a.append(n,desc,count,arrow);root.append(a)})}).catch(()=>{document.querySelector('#videos').textContent='The video archive could not load. Please refresh, or use the featured video links above.'});
